/* @lc app=leetcode id=2050 lang=kotlin */ class Solution { fun up(fin: IntArray, v: Int, x: Int) = x.also { fin[v] = maxOf(fin[v], it) } fun minimumTime(n: Int, relations: Array<IntArray>, time: IntArray): Int = relations.groupBy({ it[0] - 1 }, { it[1] - 1 }).let { g -> IntArray(n).also { d -> relations.forEach { d[it[1] - 1]++ } }.let { d -> time.copyOf().let { fin -> generateSequence((0 until n).filter { d[it] == 0 }) { f -> f.flatMap { u -> g[u].orEmpty().filter { v -> up(fin, v, fin[u] + time[v]).let { --d[v] == 0 } } }.takeIf { it.isNotEmpty() } }.count().let { fin.max() } } } } }